50	// confirmed in node_modules/@salesforce/retail-react-app/.../shared/ui/useMultiStyleConfig) in a
51	// vi.fn so its call args are inspectable, without changing what it actually returns/does. Lets
52	// the `hasError` wiring test below prove the exact props ProductItem passes through, rather than
53	// asserting a media-query-scoped computed style value jsdom does not reliably resolve (see this
54	// file's own docblock).
55	vi.mock('@salesforce/retail-react-app/app/components/shared/ui', async (importOriginal) => {
56	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/components/shared/ui')>();
57	  return {
58	    ...actual,
59	    useMultiStyleConfig: vi.fn(actual.useMultiStyleConfig),
60	  };
61	});
