238	  });
239	
240	  test('every existing caller (hideStepperAndActions omitted) is unaffected — the stepper and actions still render', () => {
241	    renderWithProviders(
242	      <ProductItem
243	        product={MOCK_LINE_ITEM}
244	        primaryAction={<button type="button">Remove</button>}
245	        secondaryActions={<button type="button">Edit</button>}
